package com.example.media_reels.CapViewimport android.content.ContentValuesimport android.content.Contextimport android.graphics.Bitmapimport android.graphics.Canvasimport android.graphics.Colorimport android.os.Buildimport android.provider.MediaStoreimport android.util.Logimport android.view.Viewimport android.widget.FrameLayoutimport java.io.OutputStreamclass CapView(context: Context) : FrameLayout(context) {    companion object {        private const val TAG = "CapView"    }    /** Capture the content of the View and save it as an image */    fun captureAndSaveView(view: View?) {        if (view == null) {            Log.e(TAG, "captureAndSaveView: View is null")            return        }        // Create Bitmap from View        val bitmap = Bitmap.createBitmap(view.width, view.height, Bitmap.Config.ARGB_8888)        val canvas = Canvas(bitmap)        // Draw background or fallback to white        view.background?.draw(canvas) ?: canvas.drawColor(Color.WHITE)        // Draw View content        view.draw(canvas)        // Save Bitmap        saveBitmapImage(bitmap)    }    internal fun saveBitmapImage(bitmap: Bitmap) {        val timestamp = System.currentTimeMillis()        val values = ContentValues().apply {            put(MediaStore.Images.Media.MIME_TYPE, "image/png")            put(MediaStore.Images.Media.DATE_ADDED, timestamp / 1000) // DATE_ADDED in seconds        }        try {            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {                values.put(MediaStore.Images.Media.RELATIVE_PATH, "Pictures/CapturedView")                values.put(MediaStore.Images.Media.IS_PENDING, true)                val uri = context.contentResolver.insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI, values)                if (uri != null) {                    context.contentResolver.openOutputStream(uri)?.use { outputStream ->                        bitmap.compress(Bitmap.CompressFormat.PNG, 100, outputStream)                    }                    values.put(MediaStore.Images.Media.IS_PENDING, false)                    context.contentResolver.update(uri, values, null, null)                }            } else {                Log.e(TAG, "Saving for versions below Android Q is not supported")            }        } catch (e: Exception) {            Log.e(TAG, "saveBitmapImage: Error saving bitmap", e)        }    }}